import numpy as np
from numba import njit
DT=np.dtype([('a',np.float64),('b',np.float64),('c',np.float64)])
@njit
def f(a,b,c):
 x=np.empty(a.size,dtype=DT)
 x['a']=-a;x['b']=b;x['c']=c
 return np.argsort(x)
try:
 print(f(np.array([1.,1.,2.]),np.array([.2,.1,.3]),np.array([2.,1.,0.])))
except Exception as e:
 print(type(e).__name__, e)
